#include "engine.hpp"
#include <cstdio>
void render(Engine&e,int n){for(int i=0;i<n;i++){float l,r;e.sample(l,r);}}
int main(){Engine e;e.config.matrixCount=0;e.parameters[P_lfo1Depth]=0;e.parameters[P_vibrato]=0;e.parameters[P_glideVibrato]=0;e.parameters[P_ampAttack]=normalized(P_ampAttack,.003);e.parameters[P_ampDecay]=normalized(P_ampDecay,.1);e.parameters[P_ampSustain]=0;e.loadParams();e.noteOn(60,.8);render(e,24000);if(e.meterVoices!=0){puts("Decayed pluck still counted");return 1;}e.prepare(48000);e.parameters[P_ampSustain]=.8;e.parameters[P_glide]=normalized(P_glide,.2);e.parameters[P_glideMode]=normalized(P_glideMode,0);e.parameters[P_bay]=0;e.loadParams();e.noteOn(36,.8);render(e,12000);e.noteOn(48,.8);render(e,2400);double during=e.meterPitch;if(during<=36||during>=48){printf("No legato slide %.2f\n",during);return 2;}render(e,16000);if(std::abs(e.meterPitch.load()-48)>.01)return 3;e.config.route=4;e.loadParams();render(e,120000);double at=e.trainPosition;e.noteOn(55,.8);render(e,48000);e.noteOff(55);render(e,48000);if(std::abs(at-e.trainPosition)>1e-6){puts("Notes moved train");return 4;}e.config.sequence=true;render(e,48000);if(std::abs(at-e.trainPosition)>1e-6){puts("Sequence moved train");return 5;}e.parameters[P_cutoff]=.9;e.loadParams();render(e,48000);if(std::abs(e.trainPosition-.9)>.001){puts("Cutoff did not move train");return 6;}e.config.sequence=false;e.prepare(48000);e.samples=readLibrary("samples");e.parameters[P_instrument]=normalized(P_instrument,8);e.parameters[P_sample]=0;e.parameters[P_sampleLoop]=1;e.parameters[P_ampSustain]=.8;e.loadParams();e.noteOn(36,.8);render(e,96000);if(e.meterVoices!=1||e.voices[0].samplePosition>=e.samples[0].data.size())return 7;puts("Mechanics: pluck count clears; overlapping notes slide; MIDI/sequence do not move trains; cutoff does; sample sustain loop plays.");return 0;}
